// src/components/AboutMe.jsx
import React, { use } from 'react';

export default function AboutMe({ theme }) {
  useEffect(() => {
    if(window.IN && typeof window.IN.parse === 'function') {
      window.IN.parse();
    }
  }, []);
  return (
    <section id="about" className="py-12">
      <h2
        className={`
          text-2xl font-bold mb-6
          ${theme === 'dark' ? 'text-yellow-400' : 'text-blue-800'}
        `}
      >
        About Me
      </h2>
      <div className="grid md:grid-cols-2 gap-8 items-start">
        {/* Left: your bio */}
        <div
          className={`
            space-y-4
            ${theme === 'dark' ? 'text-yellow-300' : 'text-blue-600'}
          `}
        >
          <p>
            I’m a Running Start student at SPSCC pursuing an A.A. in Computer Science and an
            aspiring Electrical & Computer Engineer. Over the past three years, I’ve led
            robotics teams, founded STEM outreach programs, and developed web applications
            during the Headstarter AI Fellowship.
          </p>
          <p>
            As captain of FRC Team 4450, I restructured leadership and ran rookie workshops;
            as founder of FIRST STEP ORG, I launched six FLL teams and mentored over 60
            students; and through my fellowship, I mastered HTML, CSS, JavaScript, and
            Git workflows.
          </p>
        </div>

        {/* Right: LinkedIn inline badge */}
        <div>
          <div
            className="LI-profile-badge"
            data-version="v1"
            data-size="medium"
            data-locale="en_US"
            data-type="inline"
            data-theme={theme === 'dark' ? 'dark' : 'light'}
            data-vanity="srivikaatr"
          >
            <a
              className="LI-simple-link"
              href="https://www.linkedin.com/in/srivikaatr?trk=profile-badge"
            >
              Srivikaat Ravi
            </a>
          </div>
        </div>
      </div>
    </section>
  );
}
